import {ToolRegistry} from './registry.js';

describe('ToolRegistry unit', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled (specs/hal-engine-tool-input-validation/spec.md#L18)', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type' as any}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

